GREEN="\e[32m"
BLUE="\e[34m"
YELLOW="\e[33m"
RED="\e[31m"
ORANGE="\e[33m"
RESET="\e[0m"



animate_ORANGEwords() {

for word in $1; do

     echo -e "${YELLOW}$word${RESET}"
    sleep 0.1
done
}


animate_ORANGEwords "$Sixten_HD"
animate_ORANGEwords "$Sixten_sleepy"
